// Why: the QuickJS script sandbox has no module loader, so `pm.expect` needs chai as one
// self-contained string that is evaluated inside each context.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import * as esbuild from 'esbuild'

const REPO_ROOT = path.resolve(import.meta.dirname, '..', '..')
const OUTPUT_PATH = path.join(
  REPO_ROOT,
  'src',
  'main',
  'api-client',
  'script-sandbox',
  'chai-bundle-source.ts'
)

async function buildChaiIife() {
  const result = await esbuild.build({
    stdin: {
      contents: "export * from 'chai'",
      resolveDir: REPO_ROOT,
      loader: 'js'
    },
    bundle: true,
    write: false,
    format: 'iife',
    globalName: '__orcaChai',
    platform: 'neutral',
    mainFields: ['module', 'main'],
    target: 'es2020',
    minify: true,
    legalComments: 'none'
  })
  return result.outputFiles[0].text
}

function renderModule(bundle) {
  return [
    '// Generated by config/scripts/build-api-client-chai-bundle.mjs. Do not edit.',
    `export const CHAI_BUNDLE_SOURCE: string = ${JSON.stringify(bundle)}`,
    ''
  ].join('\n')
}

const expected = renderModule(await buildChaiIife())

if (process.argv.includes('--check')) {
  const actual = existsSync(OUTPUT_PATH) ? readFileSync(OUTPUT_PATH, 'utf8') : ''
  if (actual !== expected) {
    console.error(
      'chai-bundle-source.ts is out of date. Run `pnpm run build:api-client-chai` and commit the result.'
    )
    process.exit(1)
  }
} else {
  writeFileSync(OUTPUT_PATH, expected)
  console.log(`Wrote ${path.relative(REPO_ROOT, OUTPUT_PATH)}`)
}
